---@class ResidentBondPanelAttrCell
---@field Env                           	ResidentBondPanelAttrCell               
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field ImgIcon                       	UnityEngine.RectTransform               	@ 0    
---@field TxtTitle                      	UnityEngine.RectTransform               	@ 1    
---@field ImgFill                       	UnityEngine.RectTransform               	@ 2    
---@field TxtNum                        	UnityEngine.RectTransform               	@ 3    
---@field UIFX_InforIntelligence_Activated	UnityEngine.RectTransform               	@ 4    
local ResidentBondPanelAttrCell = Class("ResidentBondPanelAttrCell")
local cardConfMgr = CardConfMgr:GetInstance()
local AttrType = {
    Num = 1,       --- 值
    Percent = 2,   --- 百分比
}

function ResidentBondPanelAttrCell:__init()

end

function ResidentBondPanelAttrCell:__delete()
    self.controller = nil
end

function ResidentBondPanelAttrCell:Awake()
    CfUtils.SetActive(self.UIFX_InforIntelligence_Activated.gameObject,false)
end

function ResidentBondPanelAttrCell:RefreshShow(data)
    self.data = data
    ---@type BasicAttrAdditionVo
    local attrAdditionVo = cardConfMgr:GetBasicAttrAdditionById(self.data.attrId)
    if isNotNull(attrAdditionVo) then
        CfUtils.FillText(self.TxtTitle,attrAdditionVo.attrAdditionName)
        local vo = cardConfMgr:GetBasicAttr(attrAdditionVo.attrId)
        if isNotNull(vo) then
            CfUtils.FillImage(self.ImgIcon, vo.icon)
        end
    end

    if self.data.upgradeType == AttrType.Num then
        local enable = self.data.playerAddition >= math.floor(self.data.maxNum/self.data.divideNum)
        self.FullRoot.enabled = enable
        if enable then
            CfUtils.FillText(self.TxtNum, self.data.playerAddition)
        else
            CfUtils.FillText(self.TxtNum, string.format("%s/<size=26><color=#C6C6C6>%s",self.data.playerAddition,math.floor(self.data.maxNum/self.data.divideNum)))
        end
        self.ImgFill.fillAmount = self.data.playerAddition/math.floor(self.data.maxNum/self.data.divideNum)
    elseif self.data.upgradeType == AttrType.Percent then
        local totalNum = self.data.maxNum/self.data.divideNum * 100
        local enable = self.data.playerAddition * 100 >= totalNum
        self.FullRoot.enabled = enable
        CfUtils.FillText(self.TxtNum,string.format("%s%%/<size=26><color=#C6C6C6>%s%%",self.data.playerAddition * 100 ,totalNum))
        self.ImgFill.fillAmount = self.data.playerAddition/(self.data.maxNum/self.data.divideNum)
    end
end

function ResidentBondPanelAttrCell:RefreshSingleShow(data)
    self:RefreshShow(data)
    CfUtils.SetActive(self.UIFX_InforIntelligence_Activated.gameObject,true)
end

function ResidentBondPanelAttrCell:OnDestroy()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
end

return ResidentBondPanelAttrCell